input.command:
mkdir -p /tmp/part35 && cat > /tmp/part35/with-deck.mjs <<'EOF'
// Test-only: copy build.nbt, add the porch deck (y2) and front steps (y1, z6) that fittings will build, for the room check.
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [src, out] = process.argv.slice(2);
const g = load(src);
for (let x = 85; x <= 94; x++) for (let z = 7; z <= 9; z++) if (g.isAir(x, 2, z)) g.set(x, 2, z, "spruce_planks");
for (let x = 88; x <= 91; x++) if (g.isAir(x, 1, 6)) g.set(x, 1, 6, "spruce_stairs", { facing: "south", half: "bottom", shape: "straight" });
g.save(out);
console.log("saved", out);
EOF
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit2/crew/part-35 && node /tmp/part35/with-deck.mjs build.nbt /tmp/part35/test.nbt && node /Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs room /tmp/part35/test.nbt --rooms rooms.json --only "Bungalow porch" 2>&1 | head -60; date

